 const warehouse=c.warehouseId?row(s,'warehouses',text(c.warehouseId)):undefined;demand(warehouse||source==='delivered','حدد مخزن رجوع المتبقي');const q=qty(c.quantity),reason=text(c.reason);const res=c.reservationId?row(s,'reservations',c.reservationId):undefined;
